// Fixtures for tic-web, generated by the real rules engine (FRONTEND §6), so
// frontend and backend agree by construction. Validated against the contracts.
//
// Usage: bun run scripts/fixtures.ts [outDir]     (default ../tic-web/src/fixtures)
// Writes:
//   payouts.json             PayoutDetail[] as of DEMO_DEFAULT_AS_OF (memo: null)
//   plan-all.<date>.json     PlanAllResponse for each slider date. Reroutes are
//                            relative to the previous date in the demo order
//                            (the first one is relative to the default date).

import { z } from "zod";
import { PayoutDetail, PlanAllResponse, type Plan } from "../src/contracts";
import { DEMO_DATES, DEMO_INVOICES, demoInvoice, planPayout, replanAll, screenPayee, toPayoutSummary } from "../src/corredor";

const outDir = (process.argv[2] ?? new URL("../../tic-web/src/fixtures/", import.meta.url).pathname).replace(/\/?$/, "/");
const defaultAsOf = process.env.DEMO_DEFAULT_AS_OF ?? "2026-10-17";

const items = await Promise.all(
  DEMO_INVOICES.map(async (d) => {
    const s = await screenPayee(d.payeeName);
    return {
      payoutId: `demo-${d.key}`,
      invoice: demoInvoice(d.key),
      screening: { status: s.status, ...(s.match ? { match: s.match, score: s.score } : {}) },
    };
  }),
);

const write = (name: string, data: unknown) => Bun.write(`${outDir}${name}`, JSON.stringify(data, null, 2) + "\n");

const details = items.map((it) => {
  const plan = planPayout({ ...it, asOf: defaultAsOf });
  return PayoutDetail.parse({ ...toPayoutSummary(it.payoutId, it.invoice, plan), invoice: it.invoice, plan, memo: null, approvals: [] });
});
await write("payouts.json", z.array(PayoutDetail).parse(details));

let previous: Plan[] = details.map((d) => d.plan!);
for (const asOf of DEMO_DATES) {
  const { plans, reroutes } = replanAll(items.map((it, i) => ({ ...it, previous: previous[i]! })), asOf);
  const body = PlanAllResponse.parse({ payouts: plans.map((p, i) => toPayoutSummary(p.payoutId, items[i]!.invoice, p)), reroutes });
  await write(`plan-all.${asOf}.json`, body);
  previous = plans;
}

console.log(`Wrote payouts.json and ${DEMO_DATES.length} plan-all files to ${outDir}`);
